     2| * IVX Senior-Developer Answer Format
     3| *
     4| * Renders the senior-developer runtime proof into the OWNER-REQUIRED strict
     5| * execution format. The owner explicitly rejected narrative prose ("Owner
     6| * Execution Mode — executing end-to-end…"); every development task must return
     7| * an evidence-only block:
     8| *
     9| *   TASK UNDERSTOOD / FILES INSPECTED / FILES CHANGED / COMMANDS RUN /
    10| *   TEST RESULT / TYPECHECK RESULT / STATUS / PROOF
    11| *
    12| * Hard enforcement (no claims without real commands):
    13| *   - No files changed      → "NO CODE CHANGED — no development was completed."
    14| *   - No tests run          → "NOT VERIFIED — tests were not run."
    15| *   - Patch could not write  → "BLOCKED — I do not have code write access."
    16| *
    17| * This module is runtime-free and deterministic (no network/filesystem/AI) so it
    18| * is fully unit-testable.
    19| */
    20|import type { IVXSeniorDeveloperRunProof } from './ivx-senior-developer-runtime';
    21|import type { IVXOwnerExecutionDecision } from './ivx-owner-execution-mode';
    22|import type { IVXWorkerJob, IVXWorkerJobResult } from './ivx-senior-developer-worker';
    23|
    24|function trimmed(value: unknown): string {
    25|  return typeof value === 'string' ? value.trim() : '';
    26|}
    27|
    28|function firstSentence(text: string): string {
    29|  const normalized = trimmed(text).replace(/\s+/g, ' ');
    30|  if (!normalized) {
    31|    return 'Execute the requested development task.';
    32|  }
    33|  const sentence = normalized.split(/(?<=[.!?])\s/)[0] ?? normalized;
    34|  return sentence.length > 160 ? `${sentence.slice(0, 157)}...` : sentence;
    35|}
    36|
    37|/** Render one validation result as raw, copy-pasteable terminal output. */
    38|function rawValidationOutput(validation: IVXSeniorDeveloperRunProof['validations'][number]): string {
    39|  return [
    40|    `$ ${validation.command}`,
    41|    validation.stdoutTail ? validation.stdoutTail.trimEnd() : '',
    42|    validation.stderrTail ? validation.stderrTail.trimEnd() : '',
    43|    validation.error ? `error: ${validation.error}` : '',
    44|    `exit code: ${validation.exitCode ?? 'null'} → ${validation.ok ? 'PASS' : 'FAIL'}`,
    45|  ]
    46|    .filter((line) => line.length > 0)
    47|    .join('\n');
    48|}
    49|
    50|export function isTypecheckCommand(command: string): boolean {
    51|  return /\b(tsc|typecheck|type-check|type\s+check)\b/i.test(command);
    52|}
    53|
    54|export function isTestCommand(command: string): boolean {
    55|  return /\btest\b/i.test(command) && !isTypecheckCommand(command);
    56|}
    57|
    58|/**
    59| * Build the senior-developer execution answer in the owner-required strict format.
    60| */
    61|export function buildSeniorDeveloperExecutionAnswer(
    62|  proof: IVXSeniorDeveloperRunProof,
    63|  decision: IVXOwnerExecutionDecision,
    64|): string {
    65|  // Guarded actions are the only path allowed to stop before executing.
    66|  if (decision.requiresApproval) {
    67|    const categories = decision.approvalCategories.join(', ') || 'a guarded action';
    68|    return [
    69|      `TASK UNDERSTOOD:\n${firstSentence(proof.goal)}`,
    70|      `FILES INSPECTED:\n${proof.repoBrain.keyFiles.slice(0, 12).join('\n') || 'none'}`,
    71|      'FILES CHANGED:\nNO CODE CHANGED — no development was completed.',
    72|      'COMMANDS RUN:\nnone — guarded action requires explicit owner confirmation before execution.',
    73|      'TEST RESULT:\nNOT VERIFIED — tests were not run.',
    74|      'TYPECHECK RESULT:\nNOT VERIFIED — typecheck was not run.',
    75|      'STATUS:\nBLOCKED',
    76|      `PROOF:\nBLOCKED — requires owner confirmation: ${categories}. Reply with the exact action and confirmation text to execute.`,
    77|    ].join('\n\n');
    78|  }
    79|
    80|  const changedFiles = proof.changedFiles;
    81|  const validations = proof.validations;
    82|  const testValidations = validations.filter((v) => isTestCommand(v.command));
    83|  const typecheckValidations = validations.filter((v) => isTypecheckCommand(v.command));
    84|  const otherValidations = validations.filter(
    85|    (v) => !isTestCommand(v.command) && !isTypecheckCommand(v.command),
    86|  );
    87|  const git = proof.gitDeployOperator;
    88|
    89|  // FILES INSPECTED — real paths the repo brain indexed for this task.
    90|  const inspected = proof.repoBrain.keyFiles.slice(0, 12);
    91|  const filesInspected = inspected.length > 0
    92|    ? inspected.join('\n')
    93|    : `indexed ${proof.repoBrain.indexedFileCount} files across ${proof.repoBrain.indexedDirectoryCount} directories`;
    94|
    95|  // FILES CHANGED — hard enforcement: real paths or the exact "no change" / "no write" line.
    96|  let filesChanged: string;
    97|  if (changedFiles.length > 0) {
    98|    filesChanged = changedFiles.join('\n');
    99|  } else if (proof.patchProposal.status === 'blocked') {
   100|    filesChanged = 'BLOCKED — I do not have code write access.';
   101|  } else {
   102|    filesChanged = 'NO CODE CHANGED — no development was completed.';
   103|  }
   104|
   105|  // COMMANDS RUN — raw command lines actually executed (validations + git/deploy).
   106|  const commandLines: string[] = otherValidations
   107|    .concat(testValidations, typecheckValidations)
   108|    .map((v) => `$ ${v.command} → exit ${v.exitCode ?? 'null'} (${v.ok ? 'PASS' : 'FAIL'})`);
   109|  if (git.github.commitAttempted) {
   110|    commandLines.push(`$ git commit/push → ${git.github.commitSha ? `committed ${git.github.commitSha}` : `not completed (${git.reason})`}`);
   111|  }
   112|  if (git.render.deployAttempted) {
   113|    commandLines.push(`$ render deploy → ${git.render.deployId ? `${git.render.deployStatus ?? 'triggered'} (${git.render.deployId})` : `not completed (${git.render.error ?? git.reason})`}`);
   114|  }
   115|  const commandsRun = commandLines.length > 0
   116|    ? commandLines.join('\n')
   117|    : 'NONE — no commands were executed.';
   118|
   119|  // TEST RESULT — raw output or the exact "not verified" line.
   120|  const testResult = testValidations.length > 0
   121|    ? testValidations.map(rawValidationOutput).join('\n\n')
   122|    : 'NOT VERIFIED — tests were not run.';
   123|
   124|  // TYPECHECK RESULT — raw output or the exact "not verified" line.
   125|  const typecheckResult = typecheckValidations.length > 0
   126|    ? typecheckValidations.map(rawValidationOutput).join('\n\n')
   127|    : 'NOT VERIFIED — typecheck was not run.';
   128|
   129|  // STATUS — DEPLOYED only when commit+deploy executed, production verified, AND
   130|  // the validation checks actually ran and passed. A deploy that looks complete
   131|  // but has no confirmed tests/typecheck is UNVERIFIED, never DEPLOYED — claiming
   132|  // DEPLOYED while tests/typecheck read "NOT VERIFIED" is exactly the dishonest
   133|  // mismatch this format must prevent.
   134|  const checksRan = testValidations.length > 0 || typecheckValidations.length > 0;
   135|  const checksPassed = checksRan && validations.every((v) => v.ok);
   136|  const deployConfirmed = git.status === 'executed'
   137|    && Boolean(git.github.commitSha)
   138|    && proof.productionVerification.ok
   139|    && proof.changedRouteVerification.ok;
   140|  let status: 'DEPLOYED' | 'UNVERIFIED' | 'LOCAL ONLY' | 'BLOCKED';
   141|  if (changedFiles.length === 0 || proof.patchProposal.status === 'blocked') {
   142|    status = 'BLOCKED';
   143|  } else if (deployConfirmed && checksPassed) {
   144|    status = 'DEPLOYED';
   145|  } else if (deployConfirmed && !checksPassed) {
   146|    // Deploy pipeline reported done, but checks were not run/confirmed — do not
   147|    // overclaim. Surface UNVERIFIED so the report matches the TEST/TYPECHECK lines.
   148|    status = 'UNVERIFIED';
   149|  } else {
   150|    status = 'LOCAL ONLY';
   151|  }
   152|
   153|  // PROOF — diff-stat-style summary derived from the applied patch operations.
   154|  const proofLines: string[] = [];
   155|  if (changedFiles.length > 0) {
   156|    proofLines.push('git diff --stat (applied patch):');
   157|    for (const filePath of changedFiles) {
   158|      const op = proof.patchProposal.operations.find((operation) => operation.path === filePath);
   159|      proofLines.push(` ${filePath} | ${op ? op.summary : 'modified'}`);
   160|    }
   161|    proofLines.push('git status --short:');
   162|    for (const filePath of changedFiles) {
   163|      proofLines.push(` M ${filePath}`);
   164|    }
   165|    if (git.github.commitSha) {
   166|      proofLines.push(`commit: ${git.github.commitSha}${git.github.branch ? ` (${git.github.branch})` : ''}`);
   167|    }
   168|    proofLines.push(`production /health: ${proof.productionVerification.ok ? 'healthy' : 'not confirmed'}; changed route: ${proof.changedRouteVerification.ok ? 'live' : 'not confirmed'}`);
   169|  } else {
   170|    proofLines.push('git diff --stat: (no changes)');
   171|    proofLines.push('git status --short: (clean)');
   172|  }
   173|  proofLines.push(`job: ${proof.jobId}`);
   174|
   175|  return [
   176|    `TASK UNDERSTOOD:\n${firstSentence(proof.goal)}`,
   177|    `FILES INSPECTED:\n${filesInspected}`,
   178|    `FILES CHANGED:\n${filesChanged}`,
   179|    `COMMANDS RUN:\n${commandsRun}`,
   180|    `TEST RESULT:\n${testResult}`,
   181|    `TYPECHECK RESULT:\n${typecheckResult}`,
   182|    `STATUS:\n${status}`,
   183|    `PROOF:\n${proofLines.join('\n')}`,
   184|  ].join('\n\n');
   185|}
