   187|/**
   188| * Build the strict execution answer from a completed worker-queue job result.
   189| *
   190| * This is the chat-side renderer for jobs created via the persistent worker
   191| * queue (`enqueueOrAttachSeniorDeveloperJob`). It mirrors the runtime-proof
   192| * renderer above but reads from the secret-safe `IVXWorkerJobResult` summary
   193| * that the worker writes to the durable proof ledger. It never fabricates
   194| * evidence: if a field is missing it surfaces the exact honest line.
   195| */
   196|export function buildSeniorDeveloperWorkerJobAnswer(
   197|  job: IVXWorkerJob,
   198|  decision: IVXOwnerExecutionDecision,
   199|): string {
   200|  const result = job.result;
   201|  const guarded = decision.requiresApproval;
   202|
   203|  // ── Guarded action: blocked before execution, require owner confirmation ──
   204|  if (guarded) {
   205|    const categories = decision.approvalCategories.join(', ') || 'a guarded action';
   206|    return [
   207|      `TASK UNDERSTOOD:\n${firstSentence(job.input.goal)}`,
   208|      'FILES INSPECTED:\n(none — guarded action halted before repo inspection)',
   209|      'FILES CHANGED:\nNO CODE CHANGED — no development was completed.',
   210|      'COMMANDS RUN:\nnone — guarded action requires explicit owner confirmation before execution.',
   211|      'TEST RESULT:\nNOT VERIFIED — tests were not run.',
   212|      'TYPECHECK RESULT:\nNOT VERIFIED — typecheck was not run.',
   213|      'STATUS:\nBLOCKED',
   214|      `PROOF:\nBLOCKED — requires owner confirmation: ${categories}. Reply with the exact action and confirmation text to execute.`,
   215|      `TASK ID:\n${job.jobId}`,
   216|      `STATUS URL:\n/api/ivx/senior-developer/worker/jobs/${job.jobId}`,
   217|    ].join('\n\n');
   218|  }
   219|
   220|  // ── Job still running — show live progress from the real queue state ──
   221|  // Guard compliance: include a `$ <phase> → exit pending` line so
   222|  // hasRawCommandOutput() returns true (the guard requires raw command output
   223|  // to allow any positive claim). Avoid the word "completed" (claimsDone).
