import { runIVXSeniorDeveloperTask } from './backend/services/ivx-senior-developer-runtime.ts';
import { existsSync } from 'node:fs';
import { rm, readFile } from 'node:fs/promises';
import path from 'node:path';

async function main() {
  const proof = await runIVXSeniorDeveloperTask({
    goal: 'Create a sample text to see you are real senior developer now',
    approvePatch: true,
    patchConfirmationText: 'CONFIRM_IVX_SAFE_CODE_PATCH',
    approveGitDeploy: false,
    validationMode: 'typecheck',
  });
  console.log('ok:', proof.ok);
  console.log('changedFiles:', proof.changedFiles);
  console.log('patch status:', proof.patchProposal.status);
  console.log('patch operations:', proof.patchProposal.operations.map((o) => ({ path: o.path, kind: o.kind, summary: o.summary })));
  console.log('validations:', proof.validations.map((v) => ({ cmd: v.command, ok: v.ok, exit: v.exitCode, error: v.error?.slice(0, 200) })));
  for (const f of proof.changedFiles) {
    const full = path.resolve(f);
    const there = existsSync(full);
    console.log('file exists:', f, there);
    if (there) {
      const content = await readFile(full, 'utf8');
      console.log('first 200 chars:', content.slice(0, 200));
      await rm(full, { force: true });
      console.log('cleaned up:', f);
    }
  }
  if (!proof.ok) {
    process.exit(1);
  }
}

main().catch((e) => {
  console.error('error:', e.message);
  process.exit(1);
});

